import socket,struct,random
def query(name, server='127.0.0.11'):
    tid=random.randint(0,65535)
    q=b''
    for part in name.split('.'): q+=bytes([len(part)])+part.encode()
    q+=b'\x00'
    pkt=struct.pack('!HHHHHH', tid,0x0100,1,0,0,0)+q+b'\x00\x01\x00\x01'
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(pkt,(server,53))
    try:
        data,_=s.recvfrom(4096)
        # parse answers
        ancount=struct.unpack('!H',data[6:8])[0]
        # skip header+question
        idx=12
        while data[idx]!=0: idx+=data[idx]+1
        idx+=5
        ips=[]
        for _ in range(ancount):
            if data[idx]&0xc0==0xc0: idx+=2
